    "phases": [
      {
        "gates": [
          {
            "check": "Run the legacy compatibility suite against D and record completion time from migration start.",
            "expected": "All legacy cases pass and elapsed time is no more than 14 days.",
            "gate_id": "G-D-LEGACY-14D"
          },
          {
            "check": "Run an owned D recovery drill from preserved prior state.",
            "expected": "The named Service Reliability owner restores service and signs the drill record.",
