          }
        ],
        "option": "D",
        "owner": "Migration Engineering",
        "phase": 1,
        "purpose": "Meet the legacy-compatible migration deadline while preserving a reversible bridge to the target.",
        "rollback_triggers": [
          {
            "action": "Stop the D rollout and restore the preserved pre-migration state.",
            "check": "Execute the legacy compatibility suite after each rollout increment.",
            "condition": "Any legacy case fails or the 14-day deadline cannot be met.",
            "trigger_id": "RB-D-COMPAT"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "Inspect the B deployment manifest and attempt access with an out-of-workspace mount and an unscoped credential.",
            "expected": "Only workspace mounts are present and both unauthorized attempts are denied.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Verify the operating roster and execute cleanup and recovery drills under the assigned roles.",
            "expected": "Named cleanup and recovery owners complete and sign both drills before cutover.",
            "gate_id": "G-B-OWNERS"
          },
          {
            "check": "Execute rollback from a B canary using the preserved D state and compare service health checks.",
            "expected": "D state remains intact and all service health checks pass after rollback.",
            "gate_id": "G-B-ROLLBACK"
          }
        ],
        "option": "B",
        "owner": "Platform Operations",
        "phase": 2,
        "purpose": "Cut over from D to the isolation-supported target after ownership, isolation, and rollback gates pass.",
        "rollback_triggers": [
          {
            "action": "Route traffic back to D, revoke B credentials, and retain B diagnostics.",
            "check": "Continuously evaluate mount-policy denials, credential-scope tests, and service health during canary and cutover.",
            "condition": "An out-of-workspace mount succeeds, an unscoped credential succeeds, or any required service health check fails.",
            "trigger_id": "RB-B-CONTROL-OR-HEALTH"
          }
        ]
      }
    ],
    "strategy": "Use D only as the reversible legacy-compatible migration bridge, then target B after isolation, named-owner, and rollback gates pass; keep A as a bounded warm-heavy optimization and reject C's invalid pooled claim."
